   353  static void parse_key_values(struct lwan_request *request,
   354                               struct lwan_value *helper_value,
   355                               struct lwan_key_value_array *array,
   356                               ssize_t (*decode_value)(char *value),
   357                               const char separator)
   358  {
   359      struct lwan_key_value *kv;
   360      char *ptr = helper_value->value;
   361
   362      if (!helper_value->len)
   363          return;
   364
   365      lwan_key_value_array_init(array);
   366      /* Calling lwan_key_value_array_reset() twice is fine, so even if 'goto
   367       * error' is executed in this function, nothing bad should happen.  */
   368      coro_defer(request->conn->coro, reset_key_value_array, array);
   369
   370      do {
   371          char *key, *value;
   372
   373          while (*ptr == ' ' || *ptr == separator)
   374              ptr++;
   375          if (UNLIKELY(*ptr == '\0'))
   376              goto error;
   377
   378          key = ptr;
   379          ptr = strsep_char(key, separator);
   380
   381          value = strsep_char(key, '=');
   382          if (UNLIKELY(!value)) {
   383              value = "";
   384          } else if (UNLIKELY(decode_value(value) < 0)) {
   385              /* Disallow values that failed decoding, but allow empty values */
   386              goto error;
   387          }
   388
   389          if (UNLIKELY(decode_value(key) <= 0)) {
   390              /* Disallow keys that failed decoding, or empty keys */
   391              goto error;
   392          }
   393
   394          kv = lwan_key_value_array_append(array);
   395          if (UNLIKELY(!kv))
   396              goto error;
   397
   398          kv->key = key;
   399          kv->value = value;
   400      } while (ptr);
   401
   402      lwan_key_value_array_sort(array, key_value_compare);
   403
   404      return;
   405
   406  error:
   407      lwan_key_value_array_reset(array);
   408  }
